mapper.select:
SELECT CI.cart_item_id AS cartItemId, CI.cart_id AS cartId, CI.product_id AS productId, CI.package_id AS packageId, CI.quantity AS quantity, CASE WHEN CI.product_id IS NOT NULL THEN 'PRODUCT' ELSE 'PACKAGE' END AS itemType, IFNULL(P.product_name, PK.package_name) AS itemName, IFNULL(P.price, PK.package_price) AS basePrice, IFNULL(P.product_status, PK.package_status) AS itemStatus, P.stock_quantity AS stockQuantity, PK.package_grade AS packageGrade, CASE WHEN CI.product_id IS NOT NULL THEN ( SELECT PI.image_url FROM PRODUCT_IMAGE PI WHERE PI.product_id = CI.product_id AND PI.image_type = 'THUMBNAIL' ORDER BY PI.display_order ASC, PI.image_id ASC LIMIT 1 ) ELSE ( SELECT PKI.image_url FROM PACKAGE_IMAGE PKI WHERE PKI.package_id = CI.package_id AND PKI.image_type = 'THUMBNAIL' ORDER BY PKI.display_order ASC, PKI.image_id ASC LIMIT 1 ) END AS thumbnailUrl FROM CART_ITEM CI INNER JOIN CART C ON CI.cart_id = C.cart_id LEFT JOIN PRODUCT P ON CI.product_id = P.product_id LEFT JOIN PACKAGE PK ON CI.package_id = PK.package_id WHERE C.member_id = #{memberId} AND CI.cart_item_id IN
#{id}
ORDER BY CI.cart_item_id DESC

mapper.delete:
DELETE CI
FROM CART_ITEM CI
INNER JOIN CART C ON CI.cart_id = C.cart_id
WHERE C.member_id = #{memberId}
  AND CI.cart_item_id IN

	#{id}

mapper.update:
UPDATE ORDERS
SET
	order_status = #{orderStatus},
	updated_at = NOW()
WHERE order_id = #{orderId}
  AND member_id = #{memberId}

mapper.select:
SELECT 'CANCEL' AS claimType, OC.cancel_id AS claimId, O.order_id AS orderId, O.order_number AS orderNumber, OC.cancel_reason AS reason, OC.cancel_status AS status, OC.cancel_amount AS refundAmount, IFNULL(P.payment_method, 'CARD') AS refundMethod, DATE_FORMAT(OC.created_at, '%Y-%m-%d %H:%i:%s') AS requestedAt, DATE_FORMAT(OC.created_at, '%Y-%m-%d %H:%i:%s') AS processedAt, ( SELECT OI.item_name_snapshot FROM ORDER_ITEM OI WHERE OI.order_id = O.order_id ORDER BY OI.order_item_id ASC LIMIT 1 ) AS repItemName, ( SELECT COUNT(*) FROM ORDER_ITEM OI WHERE OI.order_id = O.order_id ) AS itemCount FROM ORDER_CANCEL OC INNER JOIN ORDERS O ON OC.order_id = O.order_id LEFT JOIN PAYMENT P ON P.order_id = O.order_id WHERE O.member_id = #{memberId}
UNION ALL
SELECT 'RETURN' AS claimType, R.return_id AS claimId, O.order_id AS orderId, O.order_number AS orderNumber, R.return_reason AS reason, IFNULL(RF.refund_status, R.refund_status) AS status, IFNULL(RF.refund_amount, R.refund_amount) AS refundAmount, IFNULL(RF.refund_method, 'CARD') AS refundMethod, DATE_FORMAT(R.requested_at, '%Y-%m-%d %H:%i:%s') AS requestedAt, DATE_FORMAT(IFNULL(RF.processed_at, R.processed_at), '%Y-%m-%d %H:%i:%s') AS processedAt, PR.product_name AS repItemName, R.return_quantity AS itemCount FROM `RETURN` R INNER JOIN ORDERS O ON R.order_id = O.order_id INNER JOIN PRODUCT PR ON R.product_id = PR.product_id LEFT JOIN REFUND RF ON RF.return_id = R.return_id WHERE R.member_id = #{memberId} ORDER BY requestedAt DESC
